import {position} from './engine.js';

// Public, reproducible football context. Coordinates and completed events are the
// only inputs; this is not a vision model, chance-quality rating or causal test.
export function footballContext(s, t, corrected, analysis, language='en') {
 const index=Math.max(0,['en','es','pt'].indexOf(language)),pick=a=>a[index];
 const start=position(s,7,0,corrected),runner=position(s,7,t,corrected),defenderStart=position(s,102,0,corrected),defender=position(s,102,t,corrected);
 const path=analysis.passes.reduce((n,e)=>n+e.distance,0);
 const record={id:`${s.id}-football-${t.toFixed(1)}-r${corrected&&s.id==='wide'?2:1}`,record_type:'football_context',second:t,source:'calculated-from-synthetic-records',event_ids:analysis.passes.map(e=>e.id),pass_path_m:path,net_forward_pass_gain_m:analysis.forwardGain,scope:'Completed passes only; carries excluded. Progress is not chance quality.'};
 let observation,implication,definition,question;
 if(s.id==='wide'&&t>=16){
  record.width={runner_id:7,defender_id:102,start_second:0,end_second:t,runner_start_m:start,runner_end_m:runner,defender_start_m:defenderStart,defender_end_m:defender,runner_lateral_displacement_m:Math.abs(runner[1]-start[1]),defender_lateral_displacement_m:Math.abs(defender[1]-defenderStart[1]),corrected:!!corrected};
  observation=corrected?pick(['The winger still moves wide; corrected tracking keeps the defender in place. The recorded central passes remain valid.','El extremo sigue abriéndose; el registro corregido mantiene al defensor en su sitio. Los pases centrales registrados siguen siendo válidos.','O ponta continua abrindo; o registro corrigido mantém o defensor no lugar. Os passes centrais registrados continuam válidos.']):pick(['The winger runs toward the touchline while the defender shifts the same way; the completed passes travel through the centre.','El extremo corre hacia la banda mientras el defensor se desplaza en esa dirección; los pases completados avanzan por el centro.','O ponta corre para a lateral enquanto o defensor se desloca na mesma direção; os passes completos avançam pelo centro.']);
  implication=corrected?pick(['The attack still makes forward progress, but its explanation changes: the corrected record no longer supports a defender being drawn away.','El ataque sigue avanzando, pero cambia su explicación: el registro corregido ya no respalda que el defensor fuera arrastrado.','O ataque continua avançando, mas sua explicação muda: o registro corrigido já não sustenta que o defensor foi atraído.']):pick(['Passing progress and off-ball movement tell different parts of this attack. The wide run is worth following, without crediting it for the defender’s decision.','El avance por pases y el movimiento sin balón cuentan partes distintas del ataque. La carrera abierta merece atención, sin atribuirle la decisión del defensor.','O avanço por passes e o movimento sem bola contam partes distintas do ataque. A corrida aberta merece atenção, sem atribuir a ela a decisão defensiva.']);
  definition=corrected?pick(['An off-ball run is movement without the ball. Here the corrected record shows that the defender stayed put.','Una carrera sin balón es un movimiento sin tener la pelota. Aquí el registro corregido muestra que el defensor se quedó en su sitio.','Uma corrida sem bola é um movimento sem ter a bola. Aqui o registro corrigido mostra que o defensor ficou no lugar.']):pick(['An off-ball run is movement without the ball; it can offer a teammate another route.','Una carrera sin balón es un movimiento sin tener la pelota; puede ofrecer otra salida a un compañero.','Uma corrida sem bola é um movimento sem ter a bola; pode oferecer outra saída a um companheiro.']);
  question=pick(['Does the defender move toward the touchline with the runner, or stay in place?','¿El defensor se desplaza hacia la banda con el corredor o se queda en su sitio?','O defensor vai para a lateral com quem corre ou fica no lugar?']);
 }else if(analysis.regain){
  observation=analysis.passes.length?pick(['The recovery is followed by a completed pass to a teammate farther upfield. The ball now has a forward route.','Tras recuperar, un pase completado llega a un compañero más adelantado. El balón ya tiene una salida hacia delante.','Após recuperar, um passe completo chega a um companheiro mais avançado. A bola já tem uma saída para a frente.']):pick(['Possession changes at the recorded recovery. No completed forward pass has followed yet.','La posesión cambia con la recuperación registrada. Todavía no hay un pase completado hacia delante.','A posse muda na recuperação registrada. Ainda não há um passe completo para a frente.']);
  implication=analysis.shot?pick([analysis.shot.outcome==='goal'?'The finish completes an attack built after the recovery. The forward connection explains how the chance developed; the goal does not prove the press caused it.':'The save ends the attack without erasing its progression. Harbor turned a recovery into a shot; the outcome and the build-up deserve separate judgments.',analysis.shot.outcome==='goal'?'La definición culmina el ataque tras recuperar. La conexión hacia delante explica cómo se desarrolló la ocasión; el gol no prueba que la presión la causara.':'La parada termina el ataque sin borrar su avance. Harbor convirtió una recuperación en disparo; el resultado y la construcción merecen juicios separados.',analysis.shot.outcome==='goal'?'A finalização conclui o ataque após recuperar. A conexão à frente explica como a chance se desenvolveu; o gol não prova que a pressão a causou.':'A defesa encerra o ataque sem apagar seu avanço. Harbor transformou uma recuperação em chute; o resultado e a construção merecem avaliações separadas.']):pick(['Winning possession is only the start. The forward outlet is the link between recovering the ball and building an attack.','Ganar la posesión es solo el inicio. La salida hacia delante conecta la recuperación con la construcción del ataque.','Ganhar a posse é só o início. A saída para a frente conecta a recuperação à construção do ataque.']);
  definition=pick(['A transition is the change from defending to attacking.','Una transición es el cambio de defender a atacar.','Uma transição é a mudança de defender para atacar.']);
  question=pick(['After the recovery, is the next receiver ahead of the ball or beside it?','Tras recuperar, ¿el próximo receptor está por delante del balón o a su lado?','Após recuperar, o próximo receptor está à frente da bola ou ao lado?']);
 }else if(analysis.pressure){
  observation=pick(['The presser closes the gap while the receiver has the ball. The next pass has not yet produced a recorded recovery.','Quien presiona reduce el espacio mientras el receptor tiene el balón. El siguiente pase aún no ha producido una recuperación registrada.','Quem pressiona reduz o espaço enquanto o receptor tem a bola. O próximo passe ainda não produziu uma recuperação registrada.']);
  implication=pick(['Closing space puts the next passing decision in focus. Whether this pressure produces a turnover remains an open question.','Reducir el espacio centra la atención en la siguiente decisión de pase. Sigue abierto si esta presión producirá una pérdida.','Reduzir o espaço coloca a próxima decisão de passe em foco. Ainda está em aberto se essa pressão produzirá uma perda.']);
  definition=pick(['Pressing means approaching an opponent with the ball to restrict their options.','Presionar significa acercarse al rival con balón para limitar sus opciones.','Pressionar significa se aproximar do adversário com a bola para limitar suas opções.']);
  question=pick(['Is the receiver’s nearest passing option ahead of the ball or behind it?','¿La opción de pase más cercana al receptor está por delante del balón o detrás?','A opção de passe mais próxima de quem recebe está à frente da bola ou atrás?']);
 }
 return {record,observation,implication,definition,question};
}
